/**
 * Tax rates applied to an order, as label => percent.
 *
 * @param WC_Order|int $order Order object or ID.
 * @return array
 */
function perfectpixel_get_order_tax_rates( $order ) {
	$order = $order instanceof WC_Order ? $order : wc_get_order( $order );
	$rates = array();
	if ( ! $order ) {
		return $rates;
	}
	foreach ( $order->get_items( 'tax' ) as $tax_item ) {
		$percent = method_exists( $tax_item, 'get_rate_percent' ) ? $tax_item->get_rate_percent() : null;
		if ( null === $percent || '' === $percent ) {
			$percent = WC_Tax::get_rate_percent_value( $tax_item->get_rate_id() );
		}
		$rates[ $tax_item->get_label() ] = (float) $percent;
	}
	return $rates;
}
